 if(!records.isAdmin)return `<h2>Admin access</h2><p>Enter the leadership admin code.</p><form id="admin-unlock" class="form-grid"><label>Admin code<input name="code" type="password" inputmode="numeric" autocomplete="off" required></label><button class="primary">Unlock admin</button></form>`;
 if(!adminRecords)return '<p>Loading admin records…</p>';
 const a=adminRecords,name=id=>a.people.find(p=>p.id===id)?.name||'Unknown volunteer';
 const proof=(id,kind)=>a.attachments.filter(x=>x[kind]===id).map((x,i)=>`<a href="https://drive.google.com/file/d/${encodeURIComponent(x.drive_file_id)}/view" target="_blank" rel="noopener noreferrer">Evidence ${i+1}</a>`).join(' · ');
 let html='';
 if(adminTab==='mentors')html=mentorAdministration();
 if(adminTab==='past-rosters')html=renderPastRosters(a,{sessionId:pastRosterId,onlyMissing:pastOnlyMissing,includeCancelled:pastIncludeCancelled,now:new Date()});
